{
  "topic": "Types of Fractions",
  "affirmation": "You made fractions vivid with models and lively student counting.",
  "identity": "You teach by turning shapes into small, visible problems — moving from a circle to shading to fraction notation with a calm, conversational voice. You name parts out loud and use everyday examples (like cake and equal shares) so students can connect symbols to real actions.",
  "moments": [
    {
      "title": "Shape recognition moment",
      "quote": "یہ سرکل ہے۔",
      "why": "By confirming the shape you gently shifted students from seeing a whole object to noticing parts, opening the door to fraction thinking."
    },
    {
      "title": "Numerator/Denominator confusion",
      "quote": "9 اور 10 نیچے، اور 9 اوپر۔",
      "why": "This line showed students know placement rules but are still sorting meaning, giving you a clear, teachable diagnostic about notation versus concept."
    },
    {
      "title": "Cake example anchor",
      "quote": "ہم پارٹ کرتے ہیں۔",
      "why": "The cake story grounded the math in fairness and everyday choice, keeping attention high and giving students a reason to split parts."
    }
  ],
  "strength_name": "Student engagement",
  "strength_note": "You kept students active and vocal — counting out parts, answering shape checks, and responding to the cake example throughout the lesson.",
  "horizon_title": "Two-level tasks",
  "horizon_note": "Because most activities were whole-class and identical in this lesson, offering two levels of the same task (one simpler, one a bit harder) would let faster students deepen and quieter students practice at the right challenge.",
  "journey_note": "In this single lesson you reached about 75% of the targets: strong engagement and clear models created real momentum to build on.",
  "score_framing": "A 75% is a sign of forward movement — a milestone on a longer teaching journey, not a final verdict.",
  "domain_whys": {
    "high_leverage_practices": "یہ اسکور بہتر ہے کیونکہ آپ نے ماڈل دکھا کر 'یہ کیا چیز ہے؟' پوچھا اور بچوں نے 'یہ سرکل ہے' کہا — مکمل نمبر اس لیے نہیں کیونکہ آپ نے بچوں کے جواب پر ایک واضح فالو اپ سوال کر کے ان کی دلیل یا سوچ کو گہرائی میں لے جانے کا عمل نہیں دکھایا۔",
    "student_engagement": "یہ اسکور اچھا ہے کیونکہ آپ نے کیک کی حقیقی مثال دی اور طلبہ نے بار بار منہ بول کر حصہ گن کر جواب دیا — مکمل نمبر اس لیے نہیں کیونکہ بعض طلبہ نے صرف طریقہ کار کے سوالات پوچھے ('ٹیسٹ لکھیں؟') بجائے کہ مواد کے سوالات۔",
    "teacher_subject_knowledge": "یہ اسکور بہتر ہے کیونکہ آپ نے نمبریٹر اور ڈینومینیٹر کی شناخت کرائی اور 'یہ پروپر فیکشن نہیں ہے' کی درست اصلاح کی — مکمل نمبر اس لیے نہیں کیونکہ سبق میں کوئی کثیرالمرحلہ مسئلہ یا وقفہِ سوچ نہیں دیا گیا جہاں طلبہ خود چند قدم مسئلہ حل کریں۔"
  }
}
